var CreateCustomPlatformUseCase = class _CreateCustomPlatformUseCase {
  constructor() {
  }
  static getInstance() {
    if (!_CreateCustomPlatformUseCase._instance) {
      _CreateCustomPlatformUseCase._instance = new _CreateCustomPlatformUseCase();
    }
    return _CreateCustomPlatformUseCase._instance;
  }
  async execute(value) {
    await EmulatorManager.getInstance().initialize();
    const targetBasePlatform = PlatformList.getInstance().get(value.BasePlatform);
    if (!targetBasePlatform || !value.ImageFile) {
      console.error("Couldn't create custom platform. Target platform or image file is not specified.");
      return false;
    }
    if (value.ImageFormat === DiskImageFormat.QCOW2.name) {
      const imageValue = new CustomPlatformImageValue(targetBasePlatform, value.ImageFile);
      imageValue.name = value.Name;
      imageValue.description = value.Description;
      const platform10 = CustomPlatformImageWorker.create(imageValue);
      if (!platform10) {
        return false;
      }
    } else {
      const imageFiles = [];
      try {
        const files = await fs85.readdir(value.ImageFile);
        for (const file of files) {
          if (file.endsWith(".img")) {
            const filePath = path104.join(value.ImageFile, file);
            imageFiles.push(filePath);
          }
        }
      } catch (error) {
        console.error(`Error reading directory ${value.ImageFile}:`, error);
        return false;
      }
      const imageValue = new CustomPlatformImageValue(targetBasePlatform, imageFiles);
      imageValue.name = value.Name;
      imageValue.description = value.Description;
      const platform10 = PlatformFactory.getInstance().createTemporaryCustomInstance(imageValue);
      if (!platform10) {
        return false;
      }
    }
    return true;
  }
};

