// src/features/emulator-manager/application/usecase/platforms/get-downloadable-platform.ts
init_platform_list();
init_emulator_manager();
init_tizen_milestone_version_api();
init_platform3();
var GetDwonloadablePlatformUseCase = class _GetDwonloadablePlatformUseCase {
  constructor() {
  }
  static getInstance() {
    if (!_GetDwonloadablePlatformUseCase._instance) {
      _GetDwonloadablePlatformUseCase._instance = new _GetDwonloadablePlatformUseCase();
    }
    return _GetDwonloadablePlatformUseCase._instance;
  }
  async execute() {
    await EmulatorManager.getInstance().initialize();
    const versionProvider = TizenMilestoneVersionApi.getInstance();
    const milestoneVersions = await versionProvider.getAllVersions();
    console.info("All Tizen Versions:", milestoneVersions);
    const tvVersion2 = versionProvider.getTvHighestVersion();
    console.info("TV Highest Version:", tvVersion2);
    const downloadedPlatforms = PlatformList.getInstance().getList();
    const downloadablePlatforms = {};
    const downloadedTizenVersions = /* @__PURE__ */ new Set();
    let isTvDownloaded = false;
    for (const platform10 of downloadedPlatforms) {
      if (platform10.platformType === "standard" /* Standard */) {
        const imageInfo = platform10.getPlatformImage();
        if (imageInfo) {
          if (imageInfo.profile === "tizen") {
            downloadedTizenVersions.add(imageInfo.version);
          } else if (imageInfo.profile === "tv") {
            isTvDownloaded = true;
          }
        }
      }
    }
    const tizenDownloadableVersions = [];
    for (const version of milestoneVersions) {
      if (!downloadedTizenVersions.has(version)) {
        tizenDownloadableVersions.push(version);
      }
    }
    if (tizenDownloadableVersions.length > 0) {
      downloadablePlatforms["tizen"] = tizenDownloadableVersions;
    }
    if (!isTvDownloaded && tvVersion2) {
      downloadablePlatforms["tv"] = [tvVersion2];
    }
    return downloadablePlatforms;
  }
};

