init_device_template();
init_file_path_resources();
init_common_device_template_list();
init_skin();
var CreateCustomTemplateUseCase = class _CreateCustomTemplateUseCase {
  constructor() {
  }
  static getInstance() {
    if (!_CreateCustomTemplateUseCase._instance) {
      _CreateCustomTemplateUseCase._instance = new _CreateCustomTemplateUseCase();
    }
    return _CreateCustomTemplateUseCase._instance;
  }
  async execute(platformName, value) {
    await EmulatorManager.getInstance().initialize();
    const platform10 = PlatformList.getInstance().get(platformName);
    if (!platform10) {
      throw new AppError({
        code: ErrorCode.EMULATOR_PLATFORM_NOT_EXIST,
        type: "SYSTEM",
        message: `Could not get Templates. Platform named ${platformName} not exist.`
      });
    }
    const profileName = value.baseInformation?.profile;
    if (!profileName || profileName.length === 0) {
      throw new AppError({
        code: ErrorCode.PROFILE_INFORMATION_MISSING,
        type: "SYSTEM",
        message: "Target profile information is missing"
      });
    }
    const templateValue = DeviceTemplateValue.createDefaultValue(profileName);
    this.setTemplateValues(templateValue, value);
    const skinPath = value.display.skin.path;
    if (skinPath && skinPath.length !== 0) {
      console.info(`Setting template skin for ${skinPath}`);
      templateValue.skin = new Skin(skinPath);
    } else {
      console.info("SkinPath not provided. Using default skin");
    }
    templateValue.skinShape = platform10.getImageSkinShape();
    DeviceTemplateUtil.setTemplateSkin(templateValue, platform10);
    try {
      this.createDeviceTemplate(templateValue, platform10);
    } catch (error) {
      console.error(`Failed to create custom template, error: ${error.meta?.message}`);
      return false;
    }
    return true;
  }
  createDeviceTemplate(templateValue, platform10) {
    if (!templateValue) {
      console.error("TemplateValue is not present.");
      return;
    }
    const template = new DeviceTemplate();
    try {
      const storeDir = templateValue.isPlatformExtension ? platform10.getCustomDeviceTemplatePath() : FilePathResources.sdkDataDeviceCommonPath;
      template.create(templateValue, storeDir);
      if (templateValue.isPlatformExtension) {
        console.info("Platform extension: Add template to the platform.");
        platform10.addDeviceTemplate(template);
      } else {
        console.info("Not platform extension: Add template to the commonDeviceTemplateList.");
        CommonDeviceTemplateList.getInstance().addTemplate(template);
      }
    } catch (error) {
      throw new AppError({
        code: ErrorCode.PROFILE_INFORMATION_MISSING,
        type: "SYSTEM",
        message: error.message
      });
    }
  }
  setTemplateValues(templateValue, value) {
    console.debug("Setting templteValue");
    templateValue.name = value.baseInformation.name;
    templateValue.type = value.baseInformation.type;
    templateValue.profile = value.baseInformation.profile;
    templateValue.version = value.baseInformation.version;
    templateValue.priority = DeviceTemplatePriority.findPriority(value.baseInformation.priority) || DeviceTemplatePriority.CUSTOM;
    templateValue.isPlatformExtension = value.baseInformation.isPlatformExtension;
    templateValue.displayWidth = value.display.width;
    templateValue.displayHeight = value.display.height;
    templateValue.displaySize = value.display.size;
    templateValue.displaySizeUnit = value.display.sizeUnit;
    templateValue.displayDPI = value.display.dpi;
    templateValue.skinName = value.display.skin.name;
    templateValue.skinPath = value.display.skin.path;
    templateValue.ramSizeUnit = value.ram.sizeUnit;
    templateValue.ramSize = value.ram.size;
    templateValue.cpuCount = value.cpu.count;
    const additionalDevices = [];
    for (const device of value.additionalDevices) {
      const subDevice = new SubDevice(device.name);
      for (const item of device.items) {
        const deviceItem = new SubDeviceItem(item.id, item.name, item.support);
        subDevice.addSubDeviceItem(deviceItem);
      }
      for (const value2 of device.values) {
        const deviceValue = new SubDeviceValue(value2.name, value2.value, value2.unit);
        subDevice.addSubDeviceValue(deviceValue);
      }
      additionalDevices.push(subDevice);
    }
    templateValue.additionalDevices = additionalDevices;
  }
};

