// src/features/emulator-manager/application/usecase/templates/clone-custom-template.ts
init_device_template_util();
init_platform_list();
init_emulator_manager();
init_dist();
init_device_template_type();
init_device_template_priority();
var CloneCustomTemplateUseCase = class _CloneCustomTemplateUseCase {
  constructor() {
  }
  static getInstance() {
    if (!_CloneCustomTemplateUseCase._instance) {
      _CloneCustomTemplateUseCase._instance = new _CloneCustomTemplateUseCase();
    }
    return _CloneCustomTemplateUseCase._instance;
  }
  async execute(platformName, sourceTemplateName) {
    await EmulatorManager.getInstance().initialize();
    const platform10 = PlatformList.getInstance().get(platformName);
    if (!platform10) {
      throw new AppError({
        code: ErrorCode.EMULATOR_PLATFORM_NOT_EXIST,
        type: "SYSTEM",
        message: `Could not clone template. Platform named ${platformName} not exist.`
      });
    }
    const sourceTemplate = await DeviceTemplateUtil.findDeviceTemplateByName(sourceTemplateName, platform10);
    if (!sourceTemplate) {
      throw new AppError({
        code: ErrorCode.TARGET_TEMPLATE_NOT_FOUND,
        type: "SYSTEM",
        message: `Could not find source template ${sourceTemplateName} in platform ${platformName}`
      });
    }
    try {
      const newTemplateName = await this.generateUniqueTemplateName(sourceTemplateName, platform10);
      const clonedTemplateValue = sourceTemplate.value.clone();
      clonedTemplateValue.name = newTemplateName;
      clonedTemplateValue.type = DeviceTemplateType.CUSTOM;
      clonedTemplateValue.priority = DeviceTemplatePriority.CUSTOM;
      CreateCustomTemplateUseCase.getInstance().createDeviceTemplate(clonedTemplateValue, platform10);
      return newTemplateName;
    } catch (error) {
      console.error(`Failed to clone custom template, error: ${error.meta?.message}`);
      throw error;
    }
  }
  async generateUniqueTemplateName(baseName, platform10) {
    let copyCount = 1;
    let isUnique = false;
    const baseNameWithoutCopy = baseName.replace(/\(copy\d+\)$/, "");
    let newName = `${baseNameWithoutCopy}(copy${copyCount})`;
    while (!isUnique) {
      newName = `${baseNameWithoutCopy}(copy${copyCount})`;
      const existingTemplate = await DeviceTemplateUtil.findDeviceTemplateByName(newName, platform10);
      if (!existingTemplate) {
        isUnique = true;
      } else {
        copyCount++;
      }
    }
    return newName;
  }
};

