init_network_util();
init_os_util();
init_windows_tap();
init_dist();
var NetworkUseCase = class _NetworkUseCase {
  constructor() {
  }
  static getInstance() {
    if (!_NetworkUseCase._instance) {
      _NetworkUseCase._instance = new _NetworkUseCase();
    }
    return _NetworkUseCase._instance;
  }
  getTapDevices() {
    const tapDevices = NetworkUtil.getTapList();
    const osType2 = OsUtil.isWinOS ? "windows" : OsUtil.isLinuxOS ? "linux" : OsUtil.isMacOS ? "mac" : "unknown";
    let baseNetworks = [];
    if (OsUtil.isLinuxOS) {
      baseNetworks = NetworkUtil.getEthernetListForLinux();
    } else if (OsUtil.isMacOS) {
      baseNetworks = NetworkUtil.getEthernetListForMac();
    }
    return {
      tapDevices,
      baseNetworks,
      osType: osType2,
      label: OsUtil.isWinOS ? "Tap Device" : "Base Network"
    };
  }
  getTapInfo(tapName) {
    if (!tapName || typeof tapName !== "string") {
      throw new AppError({
        code: ErrorCode.INVALID_ARGUMENT,
        type: "USER",
        message: "TAP name is required"
      });
    }
    const subnet = NetworkUtil.getNetmaskFromTap(tapName);
    const gateway = NetworkUtil.getGatewayFromTap(tapName);
    const dns2 = NetworkUtil.getDnsFromTap(tapName);
    const bridgeIp = NetworkUtil.getBridgeIpAddress(tapName);
    const isValid2 = NetworkUtil.isValidTap(tapName);
    const isTapExist = NetworkUtil.isTapExist(tapName);
    const isTapInBridge = NetworkUtil.isTapInBridge(tapName);
    return {
      tapName,
      subnet,
      gateway,
      dns: dns2,
      bridgeIp,
      isValid: isValid2,
      isTapExist,
      isTapInBridge
    };
  }
  getAvailableTapName() {
    const tapName = NetworkUtil.getAvailableTapName();
    return { tapName };
  }
  async createTapDevice(tapName) {
    if (!tapName || typeof tapName !== "string") {
      throw new AppError({
        code: ErrorCode.INVALID_ARGUMENT,
        type: "USER",
        message: "TAP name is required"
      });
    }
    if (!OsUtil.isWinOS) {
      throw new AppError({
        code: ErrorCode.INVALID_ARGUMENT,
        type: "USER",
        message: "TAP device creation is only supported on Windows"
      });
    }
    await WindowsTap.createNewTap(tapName);
    return { tapName };
  }
};

