router13.post("/remote-devices/:id/connect", async (req, res) => {
  try {
    const deviceId = req.params.id;
    const deviceIP = req.params.ip;
    const repository = new LocalRemoteDeviceRepository();
    await repository.loadFromFile();
    const device = await repository.findById(deviceId);
    if (!device) {
      return res.status(404).json({
        status: "error",
        errorCode: "DEVICE_NOT_FOUND",
        message: `Device with IP ${deviceIP} not found`
      });
    }
    const connectingDevice = { ...device, status: "connecting" };
    await repository.save(connectingDevice);
    let connectionSuccess = false;
    let output = "";
    let attempt = 0;
    const maxAttempts = 2;
    while (attempt < maxAttempts && !connectionSuccess) {
      attempt++;
      try {
        const connectArgs = ["connect", `${device.ip}:${device.port}`];
        output = await executeGlobalSDBCommand(
          connectArgs,
          `Connecting to device ${device.ip}:${device.port} (Attempt ${attempt}/${maxAttempts})...`
        );
        if (!output.toLowerCase().includes("failed")) {
          connectionSuccess = true;
        }
      } catch (error) {
        if (attempt === maxAttempts) {
          throw error;
        }
      }
    }
    if (connectionSuccess) {
      const connectedDevice = { ...device, status: "connected" };
      await repository.save(connectedDevice);
      return res.status(200).json({
        status: "success",
        message: "Device connected successfully",
        remoteDevice: connectedDevice
      });
    } else {
      const failedDevice = { ...device, status: "disconnected" };
      await repository.save(failedDevice);
      return res.status(400).json({
        status: "error",
        errorCode: "CONNECTION_FAILED",
        message: `Failed to connect to remote target ${device.ip}

        You may get this message for following reasons:

        - This remote device is already connected by another one.
 - This remote device is running on a non-standard port.
 - There is no IP address, please check the physical connection.`,
        remoteDevice: failedDevice
      });
    }
  } catch (err) {
    const repository = new LocalRemoteDeviceRepository();
    await repository.loadFromFile();
    const device = await repository.findById(req.params.id);
    if (device) {
      const failedDevice = { ...device, status: "disconnected" };
      await repository.save(failedDevice);
      return res.status(500).json({
        status: "error",
        errorCode: "CONNECTION_FAILED",
        message: `Failed to connect to remote target ${device.ip}
You may get this message for following reasons:

         - This remote device is already connected by another one.
 - This remote device is running on a non-standard port.
 - There is no IP address, please check the physical connection.`,
        remoteDevice: failedDevice
      });
    } else {
      console.error("Connect Remote Device Error:", err);
      return res.status(500).json({
        status: "error",
        errorCode: "REMOTE_DEVICE_CONNECT_ERROR",
        message: "Failed to connect to remote device"
      });
    }
  }
});
