  // ─── LIST ────────────────────────────────────────────────────────
  // Mirrors: ExtensionConfigView.loadRepositoryInformations()
  //          CLIExtensions.displayExtraList()
  //
  // FILTERED: Only returns user-added custom extensions (excludes default/remote extensions)
  async getExtensions() {
    const extRepoMgr = ExtensionSdkManager.getInstance();
    const allExtensions = extRepoMgr.getCurrentExtensions();
    const customExtensions = allExtensions.filter((ext2) => ext2.isDefaultExtension !== true);
    console.log(`[ExtensionSDK API] getExtensions: Returning ${customExtensions.length} custom extensions (filtered from ${allExtensions.length} total)`);
    return customExtensions;
  }
  // ─── ADD ─────────────────────────────────────────────────────────
  // Mirrors: AddExtensionDialog.okPressed() + ExtensionConfigView.onClickAddButton()
  //
  // 1. Validate name not empty
  // 2. Validate URL not empty
  // 3. Check no duplicate name/URL
  // 4. Generate repoId = UUID
  // 5. extRepoMgr.validateRepository(url, repoId)
  // 6. Create new ExtensionInformation
  // 7. Add to currentExtensions
  // 8. writeToFile()
  async addExtension(name, repository) {
    console.log("[ExtensionSDK API] addExtension called", { name, repository });
    if (!name || name.trim().length === 0) {
      console.log("[ExtensionSDK API] addExtension: name is empty");
      return { success: false, message: "Extension name cannot be empty." };
    }
    if (!repository || repository.trim().length === 0) {
      console.log("[ExtensionSDK API] addExtension: repository is empty");
      return { success: false, message: "Repository URL cannot be empty." };
    }
    const extRepoMgr = ExtensionSdkManager.getInstance();
    const extensions = extRepoMgr.getCurrentExtensions();
    console.log("[ExtensionSDK API] Current extensions count:", extensions.length);
    for (const ext2 of extensions) {
      if (ext2.name === name) {
        console.log("[ExtensionSDK API] addExtension: duplicate name", name);
        return { success: false, message: `Extension with name "${name}" already exists.` };
      }
      if (ExtensionSdkConfig.isSameUrl(ext2.repository, repository)) {
        console.log("[ExtensionSDK API] addExtension: duplicate URL", repository);
        return { success: false, message: `Extension with URL "${repository}" already exists.` };
      }
    }
    const repoId = ExtensionSdkManager.generateRepoId();
    console.log("[ExtensionSDK API] Generated repoId:", repoId);
    let validationResult;
    try {
      console.log("[ExtensionSDK API] Validating repository...");
      validationResult = await extRepoMgr.validateRepository(repository, repoId);
      console.log("[ExtensionSDK API] Validation result:", validationResult);
    } catch (e) {
      console.error("[ExtensionSDK API] Validation error:", e);
      return { success: false, message: `Validation failed: ${e.message}` };
    }
    let newExt;
    if (validationResult.cachePath) {
      console.log("[ExtensionSDK API] Creating file-type extension");
      newExt = ExtensionSdkManager.createNewRepository(
        repoId,
        name,
        ExtensionSdkConfig.toFileUrl(validationResult.cachePath),
        true,
        validationResult.lastModifiedDate
      );
    } else {
      console.log("[ExtensionSDK API] Creating server-type extension");
      newExt = ExtensionSdkManager.createNewRepository(
        repoId,
        name,
        repository,
        true,
        null
      );
    }
    extensions.push(newExt);
    extRepoMgr.updateRepositories(extensions);
    console.log("[ExtensionSDK API] Updated extensions, count:", extensions.length);
    console.log("[ExtensionSDK API] Writing to file...");
    extRepoMgr.writeToFile();
    const pkgLoader = ExtensionPackageLoader.getInstance();
    pkgLoader.invalidatePackageCache();
    console.log("[ExtensionSDK API] Package cache invalidated for new extension");
    const result = { success: true, message: "Extension added successfully.", extension: newExt };
    console.log("[ExtensionSDK API] addExtension success:", result);
    return result;
  }
  // ─── MODIFY ──────────────────────────────────────────────────────
  // Mirrors: AddExtensionDialog (edit mode) + ExtensionConfigView.onClickModifyButton()
  //
  // 1. Validate name not empty
  // 2. Validate URL not empty
  // 3. Check no duplicate name/URL (excluding current)
  // 4. extRepoMgr.validateRepository(url, existingRepoId)
